<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Content; use Illuminate\Http\Request;
class ContentController extends Controller { public function index(Request $r){$q=Content::query()->where('status','published')->where(fn($x)=>$x->whereNull('published_at')->orWhere('published_at','<=',now()))->latest('published_at'); if($r->filled('type'))$q->where('type',$r->string('type')); if($r->filled('organisation_unit_id'))$q->where(fn($x)=>$x->whereNull('organisation_unit_id')->orWhere('organisation_unit_id',$r->integer('organisation_unit_id'))); if($r->filled('age_category'))$q->where(fn($x)=>$x->whereNull('target_age_categories')->orWhereJsonContains('target_age_categories',$r->string('age_category'))); if($r->filled('q')){$term='%'.$r->string('q').'%';$q->where(fn($x)=>$x->where('title','like',$term)->orWhere('summary','like',$term)->orWhere('body','like',$term));} return response()->json($q->paginate(min($r->integer('per_page',12),50)));} public function show(Content $content){abort_unless($content->status==='published',404);return response()->json(['data'=>$content]);} }
